### Complete Java Implementation (`AsiaPacificAirport.java`)

```java
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.*;

public class AsiaPacificAirport {
    static final Semaphore groundCap = new Semaphore(3, true); // Max 3 planes on ground
    static final Semaphore runway = new Semaphore(1, true);    // 1 shared runway
    static final Semaphore refuelTruck = new Semaphore(1, true); // 1 exclusive fuel truck
    static final BlockingQueue<Integer> gates = new ArrayBlockingQueue<>(3); // 3 gates
    static final PriorityBlockingQueue<Plane> landingQueue = new PriorityBlockingQueue<>();
    static final AtomicInteger totalPassengers = new AtomicInteger(0);
    static final AtomicInteger planesServed = new AtomicInteger(0);
    static final List<Long> waitTimes = Collections.synchronizedList(new ArrayList<>());
    static volatile boolean active = true;

    static void log(String msg) {
        System.out.printf("[%s] %s%n", Thread.currentThread().getName(), msg);
    }

    static class ATC extends Thread {
        public ATC() { super("Thread-ATC"); }
        public void run() {
            while (active || !landingQueue.isEmpty()) {
                try {
                    Plane p = landingQueue.poll(200, TimeUnit.MILLISECONDS);
                    if (p != null) {
                        groundCap.acquire(); // Reserve ground slot
                        int gate = gates.take(); // Assign free gate
                        log("ATC: Permission granted for " + p.getName() + " (Emergency:" + p.emergency + ") -> Gate-" + gate);
                        p.assignedGate = gate;
                        p.clearance.countDown(); // Signal plane thread
                    }
                } catch (InterruptedException e) { break; }
            }
            log("ATC: Sanity Check -> Gates free: " + gates.size() + "/3, Ground slots free: " + groundCap.availablePermits() + "/3");
            long min = waitTimes.stream().min(Long::compare).orElse(0L);
            long max = waitTimes.stream().max(Long::compare).orElse(0L);
            double avg = waitTimes.stream().mapToLong(l -> l).average().orElse(0.0);
            log(String.format("ATC Stats: Planes=%d, Passengers=%d, Wait(ms) Min=%d, Avg=%.1f, Max=%d", planesServed.get(), totalPassengers.get(), min, avg, max));
        }
    }

    static class Plane extends Thread implements Comparable<Plane> {
        final boolean emergency;
        final long arriveTime = System.currentTimeMillis();
        final CountDownLatch clearance = new CountDownLatch(1);
        int assignedGate;

        public Plane(int id, boolean em) {
            super("Thread-Plane-" + id);
            this.emergency = em;
        }
        public int compareTo(Plane o) {
            int c = Boolean.compare(o.emergency, this.emergency); // Emergency pre-empts normal
            return c != 0 ? c : Long.compare(this.arriveTime, o.arriveTime);
        }
        public void run() {
            try {
                log(getName() + (emergency ? " [FUEL EMERGENCY]" : "") + ": Requesting landing.");
                landingQueue.put(this);
                clearance.await(); // Wait for ATC thread
                waitTimes.add(System.currentTimeMillis() - arriveTime);

                runway.acquire();
                log(getName() + ": Landing on runway and coasting to Gate-" + assignedGate);
                Thread.sleep(300);
                runway.release();

                log(getName() + ": Docked at Gate-" + assignedGate);
                // Concurrent gate operations: Disembark/Embark, Cleaning/Supplies, Exclusive Refuel
                Thread paxOp = new Thread(() -> {
                    try {
                        int dis = ThreadLocalRandom.current().nextInt(20, 51);
                        log("Disembarking " + dis + " pax from " + getName());
                        Thread.sleep(200);
                        int emb = ThreadLocalRandom.current().nextInt(20, 51);
                        log("Boarding " + emb + " pax onto " + getName());
                        Thread.sleep(200);
                        totalPassengers.addAndGet(emb);
                    } catch (InterruptedException ignored) {}
                }, "Thread-PaxGroup-" + getName());

                Thread crewOp = new Thread(() -> {
                    try { log("Cleaning & restocking " + getName()); Thread.sleep(350); }
                    catch (InterruptedException ignored) {}
                }, "Thread-Crew-" + getName());

                paxOp.start(); crewOp.start();
                refuelTruck.acquire();
                log(getName() + ": Refuelling using exclusive truck.");
                Thread.sleep(300);
                refuelTruck.release();
                paxOp.join(); crewOp.join();

                runway.acquire();
                log(getName() + ": Undocked Gate-" + assignedGate + ", taking off.");
                Thread.sleep(300);
                gates.put(assignedGate);
                runway.release();
                groundCap.release();
                planesServed.incrementAndGet();
            } catch (InterruptedException ignored) {}
        }
    }

    public static void main(String[] args) throws Exception {
        gates.addAll(Arrays.asList(1, 2, 3));
        ATC atc = new ATC(); atc.start();
        Random rand = new Random();
        Plane[] planes = new Plane[6];
        for (int i = 1; i <= 6; i++) {
            planes[i-1] = new Plane(i, i == 6); // Plane 6 simulates fuel shortage during congestion
            planes[i-1].start();
            Thread.sleep(rand.nextInt(1500)); // 0, 1, or 2s intervals
        }
        for (Plane p : planes) p.join();
        active = false; atc.join();
    }
}
```

### Concurrency Explanation & Presentation Verification
1. **Strict Thread Identity (`log` utility)**: Every output explicitly calls `Thread.currentThread().getName()`. `Thread-ATC` only logs ATC clearances and final sanity checks; `Thread-Plane-X` logs pilot actions; `Thread-PaxGroup` and `Thread-Crew` log passenger and supply tasks. No thread ever impersonates another object.
2. **Ground & Runway Contention (`Semaphore`)**: `groundCap` (3 permits, fair) restricts total planes on the ground to 3, preventing runway deadlocks when gates are occupied. `runway` (1 permit, fair) enforces strict mutual exclusion during landing and take-off.
3. **Emergency Pre-emption (`PriorityBlockingQueue`)**: Plane 6 arrives with an emergency flag while gates are congested. Its `compareTo` implementation orders emergency planes ahead of waiting standard flights, ensuring immediate ATC clearance once a slot opens.
